before.script:
const tick = Number(check({type:'game-tick'})) || 0;
const traits = check({type:'player-traits'}) || {};
const levels = check({type:'player-level'}) || {};
const bearers = Object.keys(traits).filter(name => Array.isArray(traits[name]) && traits[name].includes('Summoned one'));
const sceneCombat = check({type:'npc-in-combat', npc:'anySceneNPC'});
const fighting = sceneCombat === true || (sceneCombat && typeof sceneCombat === 'object' && Object.values(sceneCombat).some(Boolean));
const location = String(check({type:'party-location'}) || '');
const town = ['Brookmeadow', 'Four Sages Bazaar', "Adventurer's Guild - Glowhaven Branch", "The Grand Sage's Court"].includes(location);
const approach = ['Brookmeadow', 'Pinewater River', 'Greenfield Farmlands', 'Shadowspire'].includes(location);
const originTick = Number(storage.rbOriginTick) || 0;
storage.rbTownReady = Boolean(bearers.length && tick - originTick >= 200 && town && !fighting);
storage.rbAmbushReady = Boolean(bearers.some(name => traits[name].includes('Traced Shore Record') && Number(levels[name]) >= 15) && storage.rbLead === true && tick >= Number(storage.rbLeadTick || 0) + 60 && approach && !fighting);

if(storage.rbAftermathRoll===undefined)storage.rbAftermathRoll=Math.random();
const near=['Shadowspire','Brookmeadow','Pinewater River'].includes(String(check({type:'party-location'})||''));
const alive=check({type:'npc-health',npc:"Valkazathoth'dmir"});
if(storage.rbAftermathRoll<0.333333&&near&&typeof alive==='number'&&alive>0){
 effects.push({type:'npc-placement',npc:"Valkazathoth'dmir",operation:'moveHere'});
 effects.push({type:'story',instruction:'After the party has resolved its own danger, Vladimir arrives on his own investigation of these roads. He can offer a visit to Shadowspire. He does not undo wounds, free a captive by decree, recruit himself or explain the conspiracy here. The invitation is voluntary.'});
}else effects.push({type:'story',instruction:'A route remains through Reika Kurose’s actual investigation of deliveries and witnesses. She can arrange a request to speak to Vladimir; declining it leaves her independent evidence route open. An escaped attack creates no recovered corpse or automatic component.'});

const rows=[{"name":"Guild: Beetles in the Orchard","min":1,"max":4,"rank":1,"premise":"Bronze work: Anaïs needs the orchard's young trees protected from a small pest outbreak. Posted reward: 35 marks."},{"name":"Guild: A Cellar That Rustles","min":1,"max":3,"rank":1,"premise":"Bronze work: Threadneedle Bakery's storage cellar has a persistent scratching problem. Posted reward: 30 marks."},{"name":"Guild: The Millrace Screen","min":1,"max":5,"rank":1,"premise":"Bronze work: Arlette's millrace screen is jammed, and she needs someone who can work safely around water. Posted reward: 40 marks."},{"name":"Guild: A Parcel over Westbridge","min":1,"max":4,"rank":1,"premise":"Bronze work: Loïc has a fitted buckle to deliver to the hospice. Posted reward: 25 marks."},{"name":"Guild: Loose Tile, Busy Steps","min":3,"max":7,"rank":1,"premise":"Bronze work: a loose roof tile over Chapel Steps threatens the flower stalls. Posted reward: 45 marks."},{"name":"Guild: Something in the Culvert","min":7,"max":12,"rank":1,"premise":"Bronze work: a culvert inspection stopped at fresh tracks and an unpleasant smell. Posted reward: 70 marks."},{"name":"Guild: The Quarry's Empty Face","min":8,"max":15,"rank":1,"premise":"Bronze work: Bruno needs an old cut checked before any new anchors go in. Posted reward: 80 marks."},{"name":"Guild: Ropes across Cold Water","min":10,"max":16,"rank":1,"premise":"Bronze work: a damaged service rope has left island supplies waiting on shore. Posted reward: 90 marks."},{"name":"Guild: Glass That Walks","min":15,"max":22,"rank":2,"premise":"Silver work: animated waste from a damaged workshop is making an alley unsafe. Posted reward: 130 marks."},{"name":"Guild: A Sound from the Intake","min":18,"max":27,"rank":2,"premise":"Silver work: an intake crew hears movement where nobody should be working. Posted reward: 160 marks."},{"name":"Guild: The Drowned Cargo","min":22,"max":32,"rank":2,"premise":"Silver work: an insured medical load rests in a documented wreck. Posted reward: 190 marks."},{"name":"Guild: The Empty Escort Road","min":28,"max":38,"rank":3,"premise":"Gold work: a recent escort vanished near the outer viaduct. Posted reward: 240 marks."},{"name":"Guild: A Ward with Teeth","min":32,"max":42,"rank":3,"premise":"Gold work: a decommissioned civic ward is resisting dismantling. Posted reward: 280 marks."}],t=check({type:'game-tick'});
if(storage.arOfferTick===t){skip=true;}else{
const vals=v=>typeof v==='number'?[v]:v&&typeof v==='object'?Object.values(v):[];
const levels=vals(check({type:'player-level'})).filter(v=>typeof v==='number'&&v>0),level=levels.length?Math.min(...levels):1;
const ranks=['Bronze','Silver','Gold','Platinum'];let rank=0;
for(let i=0;i<ranks.length;i++)if(vals(check({type:'player-item',item:'Guild Badge: '+ranks[i]})).some(v=>v>0))rank=i+1;
const raw=[].concat(check({type:'action-text'})||[]).filter(v=>typeof v==='string').join(' ').toLowerCase();
const status=n=>check({type:'quest-status',questId:n});
const available=rows.filter(r=>status(r.name)==='planned'&&rank>=r.rank);
const requested=available.find(r=>raw.includes(r.name.toLowerCase())||raw.includes(r.name.replace(/^Guild: /,'').toLowerCase()));
const harder=/harder|more dangerous|higher.level|challenging/.test(raw);
const suitable=available.filter(r=>level>=r.min&&(level<=r.max+5||r.rank===1));
const pool=suitable.length?suitable:harder?available:[];
const chosen=requested?requested:pool.sort((a,b)=>Math.abs((a.min+a.max)/2-level)-Math.abs((b.min+b.max)/2-level))[0];
if(!chosen){skip=true;}else{storage.arOfferTick=t;effects.push({type:'quest-init',operator:'set',value:chosen.name},{type:'story',instruction:'Aveline presents one actual eligible notice: '+chosen.premise+' This is an offer only; no acceptance, journey or payment occurs. Answer questions and allow refusal. Do not add other jobs or present an assessment sample as a live contract.'});}
}
